PROGRAM BubbleSort(OUTPUT);
VAR
  a: ARRAY [1..10] OF INTEGER;
  i, j, tmp: INTEGER;
BEGIN
  a[1] := 9; a[2] := 3; a[3] := 7; a[4] := 1; a[5] := 8;
  a[6] := 2; a[7] := 6; a[8] := 4; a[9] := 10; a[10] := 5;
  FOR i := 1 TO 9 DO
    FOR j := 1 TO 10 - i DO
      IF a[j] > a[j + 1] THEN
      BEGIN
        tmp := a[j];
        a[j] := a[j + 1];
        a[j + 1] := tmp
      END;
  FOR i := 1 TO 10 DO
    WRITE(a[i], ' ');
  WRITELN
END.
